// src/cli/repl.ts
async function startRepl(commands, initOptions) {
  const session = await init3(initOptions);
  try {
    while (true) {
      const line = await question("proton-drive> ", { enableHistory: true });
      if (line === null) {
        throw new ExitError();
      }
      const trimmed = line.trim();
      if (trimmed === "") {
        continue;
      }
      if (trimmed === "exit" || trimmed === "quit") {
        throw new ExitError();
      }
      try {
        const parts = splitQuotedLine(trimmed);
        const syntheticArgv = ["", "", ...parts];
        await runCommand(commands, syntheticArgv, initOptions, session);
      } catch (error) {
        if (isRecoverableReplError(error)) {
          console.error(error instanceof Error ? error.message : String(error));
          continue;
        }
        throw error;
      }
    }
  } finally {
    await session.dispose();
  }
}

